const ARTIFACT: &str = include_str!("../contracts/request-witnesses.generated.json");

#[derive(Deserialize)]
struct Artifact {
    current_oracle: String,
    operations: BTreeMap<String, Operation>,
    schema_version: u32,
}

#[derive(Deserialize)]
struct Operation {
    client_rejections: Vec<Value>,
    method: String,
    path: String,
    witnesses: Vec<Witness>,
}

#[derive(Deserialize)]
struct Witness {
    anthropic_beta: Vec<String>,
    body: Body,
    id: String,
    query: Vec<(String, String)>,
}

#[derive(Deserialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
enum Body {
    Empty,
    Json { value: Value },
    Multipart { parts: Vec<Part> },
}

#[derive(Deserialize)]
struct Part {
    name: String,
    #[serde(default)]
    filename: Option<String>,
}

impl Witness {
    /// The raw query exactly as axum's `RawQuery` / `Query<T>` see it.
    fn raw_query(&self) -> String {
        form_urlencoded::Serializer::new(String::new())
            .extend_pairs(self.query.iter().map(|(name, value)| (name, value)))
            .finish()
    }

    fn headers(&self) -> HeaderMap {
        let mut headers = HeaderMap::new();
        if !self.anthropic_beta.is_empty() {
            headers.insert(
                "anthropic-beta",
                HeaderValue::from_str(&self.anthropic_beta.join(","))
                    .expect("beta tokens are visible ASCII"),
            );
        }
        headers
    }
}

type Decode = fn(&Witness) -> Result<(), String>;
type WireError = (
    axum::http::StatusCode,
    axum::Json<crate::types::ErrorResponse>,
);

fn wire(error: WireError) -> String {
    format!("{:?}", error.1.0)
}

// --- body decoders --------------------------------------------------------

/// `ManagedJson<T>`: the body must be JSON and must decode into `T`.
fn json<T: DeserializeOwned>(witness: &Witness) -> Result<(), String> {
    match &witness.body {
        Body::Json { value } => serde_json::from_value::<T>(value.clone())
            .map(drop)
            .map_err(|error| format!("{}: {error}", std::any::type_name::<T>())),
        Body::Empty => Err(format!(
            "{} route requires a JSON body but the SDK sends none",
            std::any::type_name::<T>()
        )),
        Body::Multipart { .. } => Err(format!(
            "{} route requires a JSON body but the SDK sends multipart",
            std::any::type_name::<T>()
        )),
    }
}

/// `Bytes` with the empty-body alias (`work.stop`): empty or JSON `T`.
fn json_or_empty<T: DeserializeOwned>(witness: &Witness) -> Result<(), String> {
    match &witness.body {
        Body::Empty => Ok(()),
        _ => json::<T>(witness),
    }
}

/// The handler has no body extractor: whatever the SDK sends is not read.
fn ignored_body(_: &Witness) -> Result<(), String> {
    Ok(())
}

/// `ManagedMultipart` consumed by a hand-written field loop: every text part
/// must be one of the loop's accepted names; a file part (with a filename) is
/// accepted only where the loop reads file parts.
fn multipart(witness: &Witness, accepted_text: &[&str], file_parts: &[&str]) -> Result<(), String> {
    let Body::Multipart { parts } = &witness.body else {
        return Err("multipart route but the SDK did not send multipart".into());
    };
    for part in parts {
        let accepted = if part.filename.is_some() {
            file_parts.contains(&part.name.as_str())
        } else {
            accepted_text.contains(&part.name.as_str())
        };
        if !accepted {
            return Err(format!(
                "multipart part `{}` is not read by the handler",
                part.name
            ));
        }
    }
    Ok(())
}

// --- query decoders -------------------------------------------------------

/// `ManagedQuery<T>` (axum `Query<T>` = `serde_urlencoded::from_str`).
fn query<T: DeserializeOwned>(witness: &Witness) -> Result<(), String> {
    serde_urlencoded::from_str::<T>(&witness.raw_query())
        .map(drop)
        .map_err(|error| format!("{}: {error}", std::any::type_name::<T>()))
}

/// `ManagedQuery<HashMap<String, String>>`: an open query map.
fn map_query(witness: &Witness) -> Result<(), String> {
    query::<HashMap<String, String>>(witness)
}

/// The handler has no query extractor: the query is not read.
fn ignored_query(_: &Witness) -> Result<(), String> {
    Ok(())
}

/// A hand-written `RawQuery` parser.
fn raw<T>(
    witness: &Witness,
    parse: fn(Option<&str>) -> Result<T, WireError>,
) -> Result<(), String> {
    parse(Some(&witness.raw_query())).map(drop).map_err(wire)
}

/// The resource families whose DTO is chosen by the beta selector/capability.
fn surface(
    witness: &Witness,
    capability: ManagedCapability,
) -> Result<ManagedResourceApiSurface, String> {
    resource_api_surface(Some(&witness.raw_query()), &witness.headers(), capability)
}

fn stripped<T: DeserializeOwned>(witness: &Witness) -> Result<(), String> {
    serde_urlencoded::from_str::<T>(&without_beta_selector(Some(&witness.raw_query())))
        .map(drop)
        .map_err(|error| format!("{}: {error}", std::any::type_name::<T>()))
}

fn both(witness: &Witness, decoders: &[Decode]) -> Result<(), String> {
    decoders.iter().try_for_each(|decode| decode(witness))
}

// --- per-family route inputs ----------------------------------------------

fn files_list(witness: &Witness) -> Result<(), String> {
    let stripped_query = without_beta_selector(Some(&witness.raw_query()));
    match surface(witness, ManagedCapability::Files)? {
        ManagedResourceApiSurface::CapabilityBeta => stripped::<BetaFileListParams>(witness),
        ManagedResourceApiSurface::QueryBeta => {
            BetaFileCursorListParams::from_query(&stripped_query).map(drop)
        }
        ManagedResourceApiSurface::Ga => FileListParams::from_query(&stripped_query).map(drop),
    }
}

fn files_upload(witness: &Witness) -> Result<(), String> {
    surface(witness, ManagedCapability::Files)?;
    multipart(witness, &["expires_in_seconds"], &["file"])
}

fn skills_list(witness: &Witness) -> Result<(), String> {
    match surface(witness, ManagedCapability::Skills)? {
        ManagedResourceApiSurface::CapabilityBeta => stripped::<BetaSkillListParams>(witness),
        ManagedResourceApiSurface::QueryBeta | ManagedResourceApiSurface::Ga => {
            stripped::<SkillListParams>(witness)
        }
    }
}

fn skill_versions_list(witness: &Witness) -> Result<(), String> {
    match surface(witness, ManagedCapability::Skills)? {
        ManagedResourceApiSurface::CapabilityBeta => {
            stripped::<BetaSkillVersionListParams>(witness)
        }
        ManagedResourceApiSurface::QueryBeta | ManagedResourceApiSurface::Ga => {
            stripped::<SkillVersionListParams>(witness)
        }
    }
}

/// `read_multipart`: any part carrying a filename is a bundle file; the only
/// named text parts are the display title spellings and `executable_paths`.
fn skills_bundle(witness: &Witness) -> Result<(), String> {
    surface(witness, ManagedCapability::Skills)?;
    multipart(
        witness,
        &["display_name", "display_title", "executable_paths"],
        &["files[]", "files"],
    )
}

fn models_list(witness: &Witness) -> Result<(), String> {
    surface(witness, ManagedCapability::ManagedAgents)?;
    stripped::<crate::control::models::ModelListQuery>(witness)
}

fn session_events_list(witness: &Witness) -> Result<(), String> {
    query::<PageQuery>(witness)?;
    raw(witness, crate::routes::sessions::parse_event_list_order)?;
    raw(witness, crate::routes::sessions::parse_event_list_filter)
}

fn session_stream(witness: &Witness) -> Result<(), String> {
    raw(witness, crate::routes::sessions::parse_event_deltas)
}

/// `page` is a server-minted opaque cursor, never a declaration shape: the
/// witness value is replaced by a cursor this server would have minted so the
/// hand-written parser still sees every other official parameter.
fn session_list(witness: &Witness) -> Result<(), String> {
    use crate::routes::sessions::SessionListOrder;
    use crate::routes::sessions::pagination::{SessionCursor, SessionCursorDirection};
    // The cursor must have been minted for the order the same query requests.
    let order = witness
        .query
        .iter()
        .find(|(name, _)| name == "order")
        .map_or(Ok(SessionListOrder::Desc), |(_, value)| {
            SessionListOrder::parse(value).map_err(wire)
        })?;
    let cursor = SessionCursor {
        order,
        direction: SessionCursorDirection::After,
        created_at: "2026-01-01T00:00:00Z".into(),
        id: "session_witness".into(),
    }
    .encode();
    let query = form_urlencoded::Serializer::new(String::new())
        .extend_pairs(witness.query.iter().map(|(name, value)| {
            if name == "page" && !value.is_empty() {
                (name.as_str(), cursor.as_str())
            } else {
                (name.as_str(), value.as_str())
            }
        }))
        .finish();
    crate::routes::sessions::pagination::parse_session_list(Some(&query))
        .map(drop)
        .map_err(wire)
}

fn dream_list(witness: &Witness) -> Result<(), String> {
    crate::routes::dreams::parse_list_query(Some(&witness.raw_query()))
        .map(drop)
        .map_err(|error| format!("{error:?}"))
}

fn work_poll(witness: &Witness) -> Result<(), String> {
    raw(
        witness,
        crate::routes::environments::work_routes::parse_poll_params,
    )
}

fn vault_list(witness: &Witness) -> Result<(), String> {
    both(witness, &[query::<VaultListQuery>, query::<PageQuery>])
}

