fn artifact() -> Artifact {
    let artifact: Artifact = serde_json::from_str(ARTIFACT).expect("request witness artifact");
    assert_eq!(artifact.schema_version, 1, "request witness schema");
    assert!(
        !artifact.current_oracle.is_empty(),
        "current oracle version"
    );
    artifact
}

fn witness<'a>(artifact: &'a Artifact, operation: &str, id: &str) -> &'a Witness {
    artifact
        .operations
        .get(operation)
        .unwrap_or_else(|| panic!("{operation} is in the official corpus"))
        .witnesses
        .iter()
        .find(|witness| witness.id == id)
        .unwrap_or_else(|| panic!("{operation} has a `{id}` witness"))
}

#[test]
fn every_official_request_shape_decodes_into_its_route_type() {
    let artifact = artifact();
    let registry: BTreeMap<&str, (Decode, Decode)> = REGISTRY
        .iter()
        .map(|(operation, body, query)| (*operation, (*body, *query)))
        .collect();
    assert_eq!(registry.len(), REGISTRY.len(), "registry rows are unique");
    let mut failures = Vec::new();
    for (operation, entry) in &artifact.operations {
        let Some((body, query)) = registry.get(operation.as_str()) else {
            failures.push(format!(
                "{operation} ({} {}) has no route mapping in official_request_witnesses::REGISTRY",
                entry.method, entry.path
            ));
            continue;
        };
        for witness in &entry.witnesses {
            if let Err(error) = body(witness) {
                failures.push(format!(
                    "{operation} witness `{}` body: {error}",
                    witness.id
                ));
            }
            if let Err(error) = query(witness) {
                failures.push(format!(
                    "{operation} witness `{}` query: {error}",
                    witness.id
                ));
            }
        }
    }
    for operation in registry.keys() {
        if !artifact.operations.contains_key(*operation) {
            failures.push(format!(
                "{operation} is mapped in REGISTRY but absent from the official corpus (stale row)"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} official request shape(s) do not decode (SDK {}):\n  {}",
        failures.len(),
        artifact.current_oracle,
        failures.join("\n  ")
    );
}

#[test]
fn official_corpus_covers_every_operation_with_wire_witnesses() {
    // Every operation's first witness is the required-only `minimal` request
    // (`maximal` collapses onto it when the operation has no optional wire
    // field); the only pre-transport SDK refusals are the reviewed `null`
    // multipart display names, never a JSON body or query shape.
    let artifact = artifact();
    assert_eq!(artifact.operations.len(), REGISTRY.len());
    for (operation, entry) in &artifact.operations {
        assert_eq!(entry.witnesses[0].id, "minimal", "{operation}");
        for rejection in &entry.client_rejections {
            assert_eq!(
                rejection["id"], "params.display_name.null",
                "{operation}: {rejection}"
            );
            assert!(
                operation.ends_with("skills.create"),
                "{operation}: {rejection}"
            );
        }
    }
}

// Decision table (the c4f378c08 regression):
// | row | wire                                                   | route type            | effect |
// | P1  | body.precondition = {type:content_sha256, content_sha256} | MemoryUpdateParams | decodes, ContentSha256 |
// | P2  | body.precondition = {type:generation, memory_id, version, content_sha256} | MemoryUpdateParams | rejected |
// | D1  | ?expected_content_sha256=<hex>                         | MemoryDeleteParams    | decodes, Some(hex) |
// | D2  | ?expected_version=1&expected_content_sha256=<hex>      | MemoryDeleteParams    | rejected |
#[test]
fn memory_update_precondition_is_the_official_content_sha256_shape() {
    let artifact = artifact();
    let maximal = witness(&artifact, "beta.memoryStores.memories.update", "maximal");
    let Body::Json { value } = &maximal.body else {
        panic!("memory update sends JSON");
    };
    let precondition = &value["precondition"];
    assert_eq!(
        precondition["type"], "content_sha256",
        "P1 official discriminator"
    );
    let hex = precondition["content_sha256"].as_str().expect("P1 hash");
    assert_eq!(hex.len(), 64, "P1 64 hex characters");
    assert!(hex.bytes().all(|byte| byte.is_ascii_hexdigit()), "P1 hex");
    assert_eq!(
        precondition.as_object().map(|object| object.len()),
        Some(2),
        "P1 the official precondition carries exactly type + content_sha256"
    );
    let decoded: MemoryUpdateParams =
        serde_json::from_value(value.clone()).expect("P1 official body decodes");
    match decoded.precondition {
        Some(MemoryPrecondition::ContentSha256 { content_sha256 }) => {
            assert_eq!(content_sha256, hex, "P1 bound hash");
        }
        None => panic!("P1 precondition decoded to None"),
    }
    let internal = serde_json::json!({
        "content": "x",
        "precondition": {
            "type": "generation", "memory_id": "mem", "version": 1, "content_sha256": hex
        }
    });
    assert!(
        serde_json::from_value::<MemoryUpdateParams>(internal).is_err(),
        "P2 the internal generation witness is not a wire shape"
    );
}

#[test]
fn memory_delete_query_is_the_official_expected_content_sha256() {
    let artifact = artifact();
    let maximal = witness(&artifact, "beta.memoryStores.memories.delete", "maximal");
    let names: Vec<&str> = maximal
        .query
        .iter()
        .map(|(name, _)| name.as_str())
        .collect();
    assert_eq!(
        names,
        ["beta", "expected_content_sha256"],
        "D1 official query names"
    );
    let decoded: MemoryDeleteParams =
        serde_urlencoded::from_str(&maximal.raw_query()).expect("D1 official query decodes");
    let hex = decoded
        .expected_content_sha256
        .as_deref()
        .expect("D1 hash present");
    assert_eq!(hex.len(), 64, "D1 64 hex characters");
    assert!(
        serde_urlencoded::from_str::<MemoryDeleteParams>(&format!(
            "beta=true&expected_version=1&expected_content_sha256={hex}"
        ))
        .is_err(),
        "D2 expected_version is not a wire parameter"
    );
}
